-- Hand-written migration (not generated by `prisma migrate dev`): Postgres roles + Row Level
-- Security. This is Layer 2 of tenant isolation — defense in depth behind the Prisma Client
-- Extension in src/server/db.ts, which is Layer 1 and does the filtering the app relies on daily.
--
-- Two runtime roles, deliberately separate from the migration/owner role that ran this file:
--
--   app_user       — used by the Next.js app for all tenant-facing requests (DATABASE_URL, via
--                    the Supabase transaction pooler). RLS applies to it in full. Every query it
--                    runs must be preceded by `SET LOCAL app.tenant_id = '<tenant uuid>'` (see
--                    withTenant() in src/server/db.ts) or RLS silently returns zero rows.
--   platform_user  — used ONLY by the super-admin/(platform) route handlers (PLATFORM_DATABASE_URL).
--                    Has BYPASSRLS, so it can list every tenant. Kept on a completely separate
--                    connection from app_user so a bug in tenant-facing code can never reach it.
--
-- Neither role is the table owner, and neither has CREATEDB/CREATEROLE/SUPERUSER. Only the
-- DIRECT_URL owner role (Supabase's `postgres` role) can run migrations.
--
-- IMPORTANT — manual step after this migration runs (deliberately not in this file, so a real
-- password never lands in git history): in the Supabase SQL editor, run
--   ALTER ROLE app_user WITH LOGIN PASSWORD '<generate a strong secret>';
--   ALTER ROLE platform_user WITH LOGIN PASSWORD '<a different strong secret>';
-- then put those into DATABASE_URL and PLATFORM_DATABASE_URL respectively.

-- ---------------------------------------------------------------------------
-- Roles
-- ---------------------------------------------------------------------------

DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'app_user') THEN
    CREATE ROLE app_user NOLOGIN;
  END IF;

  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'platform_user') THEN
    CREATE ROLE platform_user NOLOGIN BYPASSRLS;
  ELSE
    ALTER ROLE platform_user BYPASSRLS;
  END IF;
END
$$;

GRANT USAGE ON SCHEMA public TO app_user, platform_user;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user, platform_user;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user, platform_user;

-- So tables created by future migrations (run by the owner role) are automatically granted to
-- both runtime roles without a manual GRANT each time.
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_user, platform_user;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT USAGE, SELECT ON SEQUENCES TO app_user, platform_user;

-- ---------------------------------------------------------------------------
-- Row Level Security
--
-- Every tenant-scoped table gets the same policy: a row is visible/writable only when its
-- "tenantId" column equals the session's app.tenant_id setting. `current_setting(..., true)`
-- returns NULL rather than erroring when unset, and "tenantId" = NULL is never true — so a
-- connection that forgets to SET LOCAL app.tenant_id sees zero rows (fails closed), not everyone
-- else's data.
--
-- FORCE ROW LEVEL SECURITY matters because without it, the table OWNER role bypasses RLS
-- entirely. app_user is never the owner, so this is pure defense in depth — but it's what
-- protects us if a future migration or a misconfiguration ever runs as the owner role by mistake.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'Branch', 'BranchSettings', 'TaxRule',
    'User', 'Role', 'Membership', 'Invite', 'StaffPin',
    'Category', 'MenuItem', 'ItemVariant', 'ModifierGroup', 'Modifier',
    'MenuItemModifierGroup', 'BranchMenuItem',
    'Floor', 'RestaurantTable',
    'Customer', 'CustomerAddress',
    'Order', 'OrderLine', 'OrderLineModifier', 'OrderDiscount', 'Payment', 'OrderEvent',
    'Subscription', 'AuditLog'
  ]
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING ("tenantId" = current_setting(''app.tenant_id'', true)) WITH CHECK ("tenantId" = current_setting(''app.tenant_id'', true))',
      t
    );
  END LOOP;
END
$$;
